"""Explicit main-reader decisions after viewing scan 082 blind crops."""
from pathlib import Path
import csv,json,subprocess,sys
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[1]
items={x['box']:x for x in json.loads((R/'second/147_scan082_comparison.json').read_text())['items']}
decisions=[]
def add(b,groups,final=None,ink=None):
 key=f'082-B{b:02d}'; a=items[key]
 decisions.append(dict(box=key,crop=f'crops/blind/147_scan082/{key}.png',ink=ink or ' '.join(g[2] for g in groups),changed=final is not None and final!=a['first'],final=final if final is not None else a['first'],token_resolutions=[dict(operations=o,decision=d,ink=e) for o,d,e in groups]))
add(4,[([0],'Add local doubt to the cancelled insertion.','The a and tall d/f-like strokes survive, but the strike crosses the small bodies of défini; not every letter can be certified.'),([1],'Keep two insertion wrappers; the layer is equivalent.','Both a défini and retrouve are on the raised replacement baseline; only the former is cancelled.')],items['082-B04']['first'].replace(r'\deleted{a défini}',r'\deleted{\unsure{a défini}}'))
add(5,[([0,1,2,3,7],'Retain edition display and equivalent star syntax.','The digits are 106 and the star stands over M; display delimiters and braces do not change the reading.'),([4,5,6],'Keep the cancelled G-double-prime/G-prime candidates; include the comma within the local doubt.','The two live primes are separate and clear. The following low hook, loop and upper marks intersect diagonal hatching; neither an independent comma nor beta with a subscript is secured.')],items['082-B05']['first'].replace(r'\deleted{,\unsure{G\'\'|G\'}}',r'\deleted{\unsure{,G\'\'|,G\'}}') if False else items['082-B05']['first'].replace("\\deleted{,\\unsure{G''|G'}}","\\deleted{\\unsure{,G''|,G'}}"))
add(6,[([0,1],'Join the physical line-break hyphen.','The first line ends carté- and the next begins sien; this is the same word cartésien.'),([2],'Retain connexe.','After groupoïde the low connected c-o-n-n-e-x-e succession extends to a separate terminal comma; the final crossed return is not the m-e ending of comme.'),([3,4,5,6],'Retain equivalent mathematical syntax.','The M-star and double-diagonal Z with C-prime exponent are the same ink in both readings.')])
add(7,[([0,1],'Retain aussi.','The short a-u opening is followed by low linked s strokes and a final i dot; no separate medial n is established.'),([2,3],'Retain en tant qu\'ext.','The preceding line ends en. The next begins a tall t, low a/n and another t, then q with a long descender, u and apostrophe before the recurrent ext. form. There is no b or l shaft supporting double.'),([4,5,6],'Preserve the old G-prime candidate and put its comma within the doubt.','The clear first G is followed immediately by diagonal hatching; neither the comma nor a beta subscript can be separated confidently from the covered old index.'),([7,8,9,10,11,12],'Keep equivalent exponent and alphabet syntax.','Both integer symbols have double diagonals and their exponents are C and C-prime.'),([13],'Do not add a comma after the parenthesis.','The closing parenthesis is followed by blank baseline before une; no separate punctuation stroke appears.')],items['082-B07']['first'].replace("\\deleted{,\\unsure{G'}}","\\deleted{\\unsure{,G'}}"))
add(8,[([0,1,2],'Keep the cancelled G-prime candidate with its comma doubtful.','The small curve and upper mark are covered by oblique hatching; beta with a subscript is not a secure recovery.'),([3,4],'Retain equivalent double-struck syntax.','The Z has doubled diagonal ink and the exponent contains C, a disjoint-union sign and C-prime.'),([5],'Mark the terminal point as uncertain.','The extra right-edge crop (1620,1735,1689,1870) shows a small dark projection joined to the black scan edge at the expected period position. It cannot securely distinguish punctuation from the edge.'),([6,7],'Add the visible underline beneath le, but no extra comma after (105).','A separate low stroke runs under le. The curved stroke after 105 is its closing parenthesis; there is no second comma to its right.')],items['082-B08']['first'].replace("\\deleted{,\\unsure{G'}}","\\deleted{\\unsure{,G'}}").replace('tordu.','tordu\\unsure{.}').replace('(105) le','(105) \\uline{le}'))
add(9,[([0,1,2,3,4,8,12,14,19,23,24],'Retain edition layout and equivalent grouping.','The number is 107; there are two upper objects and one lower object. Extra empty cells, braces and ampersand conventions change no ink.'),([5,6,7,9,10,11],'Keep the old G-prime candidates; move the following comma into the cancellation and doubt.','The lower return immediately after each hatched middle index is part of the covered old group. There is no independent live comma between that hatching and the clear final G-double-prime. A beta with subscript is not settled.'),([13,18],'Retain the locally uncertain downward endpoint.','The vertical shaft terminates in a short dark return/flick, without a clearly separable two-sided head. The second reading makes it more definite than the crop allows.'),([15,16,17,20,21,22],'Keep the cancelled final-index candidates with their commas locally doubtful.','The phi label has two clear live primes; the later index and the lower-object extra index are covered by oblique strokes. The apparent comma lies among those strokes and beta cannot be certified.')],items['082-B09']['first'].replace("\\deleted{\\unsure{G'}},G''","\\deleted{\\unsure{G',}}G''").replace("\\deleted{,\\unsure{G'}}","\\deleted{\\unsure{,G'}}"))
add(10,[([0,1],'Retain 81.','Despite pale pencil and enlargement blur, the first digit has two joined loops; the second has an angled upper entry and one long descending stem. These support 8 and 1.')])
subprocess.run([sys.executable,str(R/'scripts/write_audit.py')],input=json.dumps(dict(scan=82,second_reader='/root/blind_c',decisions=decisions)),text=True,check=True)
with (R/'root_visual_review.tsv').open('a',newline='') as f:
 w=csv.writer(f,delimiter='\t');now=datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
 for name in [f'082-B{i:02d}.png' for i in range(4,11)]+['082-B08-right-edge.png']:
  w.writerow([82,'crops/blind/147_scan082/'+name,'/root',now,'viewed and adjudicated'])
